package dev.pathland.view.core.signal

import java.util.function.BiPredicate
import java.util.function.UnaryOperator

/** A writable signal backed by a reactive graph node. */
internal class WritableSignalImpl<T>(
    private var value: T,
    private val equal: BiPredicate<T, T>,
    name: String?,
) : ReactiveNode(name), WritableSignal<T> {

    override fun get(): T {
        recordDependency()
        return value
    }

    override fun set(value: T) {
        if (equal.test(this.value, value)) return
        checkWriteAllowed()
        this.value = value
        version++
        propagate()
    }

    override fun update(fn: UnaryOperator<T>) {
        set(fn.apply(value))
    }

    override fun asReadonly(): Signal<T> = Signal { get() }
}
===== Scheduler =====
package dev.pathland.view.core.signal

import java.util.ArrayDeque

/** Synchronous effect scheduler (flushes to quiescence at the outermost write). */
internal object Scheduler {
    private val QUEUE = ArrayDeque<Effect>()
    private var flushing = false

    @Synchronized
    fun schedule(effect: Effect) {
        if (!effect.scheduled) {
            effect.scheduled = true
            QUEUE.add(effect)
        }
        flush()
    }

    @Synchronized
    fun flush() {
        if (flushing) return
        flushing = true
        try {
            while (QUEUE.isNotEmpty()) {
                val effect = QUEUE.poll()
                effect.scheduled = false
                effect.runIfScheduled()
            }
        } finally {
            flushing = false
        }
    }

    /** Drop a destroyed effect from the queue. */
    @Synchronized
    fun cancel(effect: Effect) {
        QUEUE.remove(effect)
        effect.scheduled = false
    }
}
===== Effect =====
package dev.pathland.view.core.signal

/** A reactive effect (Angular-style `effect`). */
internal class Effect(
    private val fn: Runnable,
    options: EffectOptions,
    name: String?,
) : ReactiveNode(name), EffectRef {

    @JvmField var scheduled: Boolean = false

    init {
        allowSignalWrites = options.allowSignalWrites()
        if (!options.manualCleanup()) {
            schedule()
        }
    }

    fun schedule() {
        Scheduler.schedule(this)
    }

    fun runIfScheduled() {
        if (!dirty) return
        refreshProducers()
        dirty = false
        if (!firstRun && !depsChanged()) return
        firstRun = false
        ReactiveContext.push(this)
        val previous = producers.toList()
        resetProducers()
        try {
            fn.run()
            error = null
        } catch (t: Throwable) {
            error = t
            restoreProducers(previous)
            throw EffectException("Effect '${describe()}' threw during flush", t)
        } finally {
            ReactiveContext.pop()
        }
    }

    private fun restoreProducers(previous: List<ProducerEdge>) {
        resetProducers()
        for (edge in previous) {
            producers.add(edge)
            edge.node.consumers.add(this)
        }
        dirty = false
    }

    override fun destroy() {
        Scheduler.cancel(this)
        resetProducers()
        dirty = false
    }
}
===== ReactiveContext =====
package dev.pathland.view.core.signal

import java.util.ArrayDeque

/** The reactive evaluation context: a thread-local stack of consumers. */
internal object ReactiveContext {
    private val STACK: ThreadLocal<ArrayDeque<ReactiveNode>> =
        ThreadLocal.withInitial { ArrayDeque() }

    /** The consumer currently evaluating, or null outside any reactive context. */
    fun current(): ReactiveNode? = STACK.get().peek()

    /** The underlying stack (used by `Signals.untracked`). */
    fun stack(): ArrayDeque<ReactiveNode> = STACK.get()

    /** Whether [node] is currently being evaluated (reentrancy guard). */
    fun contains(node: ReactiveNode): Boolean = STACK.get().contains(node)

    fun push(node: ReactiveNode) {
        val stack = STACK.get()
        if (stack.contains(node)) {
            throw IllegalStateException(
                "Circular signal dependency detected while evaluating '${node.describe()}'",
            )
        }
        stack.push(node)
    }

    fun pop() {
        STACK.get().pop()
    }
}

